	onDestroy(() => {
		if (!isStaticMode()) {
			off('tasks', handleTaskUpdate);
			off('agents', handleAgentEvent);
			unsubscribe(['tasks', 'agents']);
		}
	});

	// Load dashboard when project is ready and reload on project change.
	// Gates on isProjectInitialized() to prevent loading with wrong/missing project context.
	$effect(() => {
		const version = getProjectVersion();
		const ready = isProjectInitialized();
		if (!ready) return;
		loadDashboard();
	});
</script>

<div class="flex flex-col gap-6 p-6" data-testid="dashboard">
	<h1 class="text-2xl font-bold">Dashboard</h1>

	{#if error}
		<!-- Error state -->
		<div
			class="flex items-center gap-3 rounded-lg border border-destructive/50 bg-destructive/10 p-4"
			role="alert"
			data-testid="dashboard-error"
		>
			<AlertTriangle class="size-5 text-destructive" />
			<div>
				<p class="text-sm font-medium text-destructive">Failed to load dashboard</p>
				<p class="text-xs text-muted-foreground">{error}</p>
			</div>
			<button
				class="ml-auto text-xs text-muted-foreground underline hover:text-foreground"
				onclick={loadDashboard}
			>
				Retry
			</button>
		</div>
	{/if}

	{#if loading}
		<!-- Loading skeleton -->
		<div data-testid="dashboard-skeleton">
			<!-- Active work skeleton -->
			<div class="mb-6">
				<Skeleton class="mb-2 h-5 w-32 ds-shimmer" />
				<div class="flex gap-3">
					<Skeleton class="h-20 w-72 ds-shimmer" />
				</div>
			</div>

			<!-- Status summary skeleton -->
			<div class="mb-6">
				<Skeleton class="mb-3 h-5 w-40 ds-shimmer" />
				<div class="grid gap-4 md:grid-cols-4 lg:grid-cols-7">
					{#each Array(7) as _}
						<Skeleton class="h-24 ds-shimmer" />
					{/each}
				</div>
			</div>

			<!-- Needs attention skeleton -->
			<div>
				<Skeleton class="mb-3 h-5 w-40 ds-shimmer" />
				<div class="grid gap-3 md:grid-cols-2 lg:grid-cols-4">
					{#each Array(4) as _}
						<Skeleton class="h-20 ds-shimmer" />
					{/each}
				</div>
			</div>
		</div>
	{:else}
		<!-- AC: @ui-dashboard-overview ac-1 — Active work section -->
		<section data-testid="active-work-section">
			{#if hasActiveWork}
				<div class="mb-4">
					<div class="flex items-center gap-2 mb-2">

			if (countsInterval) clearInterval(countsInterval);
		};
	});

	// Load counts when project store is initialized and on every project change.
	// This replaces the old onMount loadCounts() call which could fire before
	// loadProjects() completed, causing stale/wrong-project badge counts.
	$effect(() => {
		const version = getProjectVersion();
		const ready = isProjectInitialized();
		if (!ready) return;

		// Initial load (version === 0) and subsequent project switches (version > 0)
		loadCounts();

		// Set up polling interval on first ready signal
		if (!countsInterval) {
			countsInterval = setInterval(loadCounts, 30000);
		}
	});

	async function loadCounts() {
		try {
			const [sessionData, obsResponse, inboxResponse, tasksResponse] = await Promise.all([
				fetchSessionContext(),
				fetchObservations({ resolved: false }),
				fetchInbox({ limit: 0 }),
				fetchTasks({ status: 'pending_review', limit: 0 })
			]);

			sessionContext = sessionData;
			unresolvedObservationsCount = obsResponse.total;
			inboxCount = inboxResponse.total;
			pendingReviewCount = tasksResponse.total;
		} catch (err) {
			console.error('Failed to load sidebar counts:', err);
		}
	}
</script>

<!-- AC: @ui-app-shell ac-1 — Collapsible sidebar with grouped navigation -->
<Sidebar>
