				session: null,
				observations: [],
				agents: [],
				workflows: [],
				conventions: [],
			};

			await page.route('**/kspec-snapshot.json', (route) => {
				route.fulfill({
					status: 200,
					contentType: 'application/json',
					body: JSON.stringify(snapshot),
				});
			});

