			// Force static mode: intercept health check to fail, serve a snapshot instead
			let sessionApiFetched = false;

			await page.route('**/health', (route) => {
				route.fulfill({ status: 503, body: 'Service Unavailable' });
			});

			const snapshot = {
				version: '0.1.0',
