		route.fulfill({ status: 503, body: 'Service Unavailable' });
	});

	// Serve snapshot data
	await page.route('**/kspec-snapshot.json', (route) => {
		route.fulfill({
			status: 200,
			contentType: 'application/json',
			body: JSON.stringify(snapshot),
		});
	});
}

test.describe('Static Mode Project Initialization', () => {
